export async function resumeSession(
  page: Page,
  signedIn: Locator,
  timeout = 180_000
): Promise<void> {
  const watch = watchRefusedRequests(page);
  const outcome = await resumed(page, signedIn, timeout).finally(watch.stop);
  if (outcome.kind === 'signed-in') return;
